_PB = [("Ang kasundaluhan ang tagapangalaga ng kapayapaan.", "The soldiers are the guardians of peace."), ("Sila ang kalimitang sumasabak sa kapahamakan at kaguluhan upang maproteksyunan ang bayan.", "They are ordinarily the ones who plunge into danger and violence in order to protect the country."), ("Binabagtas nila ang karagatan, kapatagan, at kabundukan, sa kasukal-sukalan, at kadulu-duluhang lugar man o kung saan man naroon ang kalaban.", "They traverse the ocean, plains and mountains, in the thickest and most remote places, or wherever the enemy is."), ("Kahit may kakulangan man sa armas at kagamitan, buo ang kanilang kaloobang humarap sa kaaway ng lipunan.", "Even if there is a shortage of arms and equipment, their will is whole to face the enemy of society."), ("Sumisimbolo sila ng kagitingan, katapangan, at kadakilaan.", "They symbolize valor, bravery and greatness."), ("Kaya mga kasamahan, mga kaibigan, at mga kapwa Pilipino, huwag nating kalimutan ang kabayanihan ng ating mga sundalo.", "So, colleagues, friends and fellow Filipinos, let us not forget the heroism of our soldiers.")]
